from core.utils import slugify, compute_total

def name_and_total(records, field):
    """Slugify the first record's name and compute the total of the given numeric field."""
    if not records:
        return {"name": "", "total": 0.0}

    name = slugify(getattr(records[0], "name", ""))
    total = compute_total(records, field)

    return {"name": name, "total": round(total, 3)}
